#!/usr/bin/env bash
# Prints the Homebrew formula for a published pominspect release.
#
#   .github/homebrew/formula.sh 0.0.1 > Formula/pominspect.rb
#
# Reads the checksums from the release's .sha256 assets, so the release must
# already be published.
set -euo pipefail

version="${1:?usage: formula.sh <version without v>}"
repo="RaccoonDev/pominspect"
base="https://github.com/${repo}/releases/download/v${version}"

sha() {
  local sum
  sum="$(curl -fsSL "${base}/pominspect-v${version}-$1.tar.gz.sha256" | cut -d' ' -f1)"
  [[ "$sum" =~ ^[0-9a-f]{64}$ ]] || { echo "bad checksum for $1: '$sum'" >&2; exit 1; }
  echo "$sum"
}

mac_arm="$(sha aarch64-apple-darwin)"
mac_intel="$(sha x86_64-apple-darwin)"
linux_arm="$(sha aarch64-unknown-linux-musl)"
linux_intel="$(sha x86_64-unknown-linux-musl)"

cat <<EOF
# Generated by https://github.com/${repo}/blob/main/.github/homebrew/formula.sh
class Pominspect < Formula
  desc "Terminal UI for exploring a Maven build's effective POM and dependency tree"
  homepage "https://github.com/${repo}"
  version "${version}"

  on_macos do
    on_arm do
      url "${base}/pominspect-v${version}-aarch64-apple-darwin.tar.gz"
      sha256 "${mac_arm}"
    end
    on_intel do
      url "${base}/pominspect-v${version}-x86_64-apple-darwin.tar.gz"
      sha256 "${mac_intel}"
    end
  end

  on_linux do
    on_arm do
      url "${base}/pominspect-v${version}-aarch64-unknown-linux-musl.tar.gz"
      sha256 "${linux_arm}"
    end
    on_intel do
      url "${base}/pominspect-v${version}-x86_64-unknown-linux-musl.tar.gz"
      sha256 "${linux_intel}"
    end
  end

  def install
    bin.install "pominspect"
  end

  def caveats
    <<~EOS
      pominspect runs Maven to inspect a project. It needs a JDK and either
      the project's ./mvnw or \`mvn\` on your PATH.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/pominspect --version")
  end
end
EOF
